function inFence(text: string, at: number) {
  const prefix = text.slice(0, at);
  const line = prefix.split(/\r\n?|\n/).length - 1;
  // Fence maps include their closer and exclude the following line. Complete
  // the prefix so an open fence includes an empty EOF line, even after CR.
  return new MarkdownIt({ html: false }).parse(prefix + '\n\n', {})
    .some(token => token.type === 'fence' && token.map !== null && token.map[1] > line);
}

replace:
function inFence(text: string, at: number) {
  let open: string | null = null;
  const lines = text.slice(0, at).split('\n');
  for (const [index, line] of lines.entries()) {
    const match = /^ {0,3}(`{3,}|~{3,})/.exec(line);
    const fence = match?.[1];
    if (!fence) continue;
    if (!open) {
      // Backticks cannot occur in a backtick fence's info string (CommonMark4.5).
      // Adjacent marker ticks were already consumed by the greedy fence match.
      if (fence[0] !== '`' || !line.slice(match![0].length).includes('`')) open = fence;
    }
    else if (fence[0] === open[0] && fence.length >= open.length && /^[ \t]*$/.test(line.slice(match![0].length))) {
      // A newline on the closing delimiter must not turn it into literal code.
      if (index === lines.length - 1) return true;
      open = null;
    }
  }
  return open !== null;
}
